CustomField.formula:
if ( isblank( Friday_Time_In__c) && isblank ( Friday_Time_Out__c), 0,

if ( isblank(Friday_Lunch_End__c) && isblank(Friday_Lunch_Start__c),

( 

(floor(Friday_Time_Out_Proxy__c) + (Friday_Time_Out_Proxy__c- floor(Friday_Time_Out_Proxy__c))/60*100)

- (floor(Friday_Time_In_Proxy__c) + (Friday_Time_In_Proxy__c- floor(Friday_Time_In_Proxy__c))/60*100)

),

( 

(floor( Friday_Lunch_Start_Proxy__c ) + (Friday_Lunch_Start_Proxy__c  - floor(Friday_Lunch_Start_Proxy__c ))/60*100)

- (floor(Friday_Time_In_Proxy__c) + (Friday_Time_In_Proxy__c- floor(Friday_Time_In_Proxy__c))/60*100)

)

))
